{
 "genere": "prevedi",
 "titolo": "Cosa restituiscono i vettori?",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run():
	var current_pos: Vector2 = Vector2(10, 20)
	var velocity: Vector2 = Vector2(5, 5)
	current_pos += velocity * 3
	return current_pos
",
   "domanda": "Quanto vale `current_pos` alla fine?",
   "spiegazione": "`velocity * 3` moltiplica ogni componente per 3, ottenendo `Vector2(15, 15)`. Aggiunto a `Vector2(10, 20)`, dà `Vector2(25, 35)`."
  },
  {
   "codice": "extends RefCounted


func run():
	var v: Vector2 = Vector2(3, 4)
	return v.length()
",
   "domanda": "Che numero restituisce `run()`?",
   "spiegazione": "La lunghezza di un vettore si calcola con il teorema di Pitagora: radice quadrata di $3^2 + 4^2$, cioè $\sqrt{9 + 16} = \sqrt{25} = 5$."
  },
  {
   "codice": "extends RefCounted


func run():
	var v: Vector2 = Vector2(50, 100)
	var n: Vector2 = v.normalized()
	return n.length()
",
   "domanda": "Quanto vale la lunghezza del vettore normalizzato `n`?",
   "spiegazione": "Normalizzare un vettore significa ridurne la lunghezza a 1 mantenendo inalterata la sua direzione. Qualsiasi vettore normalizzato diverso da zero ha sempre lunghezza 1."
  },
  {
   "codice": "extends RefCounted


func run():
	var pos: Vector2 = Vector2(0, 0)
	var target: Vector2 = Vector2(10, 0)
	pos = pos.move_toward(target, 15)
	return pos
",
   "domanda": "Quanto vale `pos` alla fine?",
   "spiegazione": "`move_toward` sposta il punto verso il bersaglio della distanza indicata (15), ma si ferma esattamente sul bersaglio senza oltrepassarlo. Il risultato è `Vector2(10, 0)`."
  },
  {
   "codice": "extends RefCounted


func run():
	var start: Vector2 = Vector2(5, 5)
	var end: Vector2 = Vector2(5, 10)
	return start.direction_to(end)
",
   "domanda": "Quale Vector2 restituisce `run()`?",
   "spiegazione": "`direction_to()` restituisce la direzione normalizzata da `start` a `end`. La distanza è 5 solo lungo l'asse y (verso il basso), quindi la direzione normalizzata è `Vector2(0, 1)`."
  }
 ]
